// Join Patent, Orange Book, ANDA/Paragraph IV, and Market data per drug and
// compute a weighted 0-100 Generic Opportunity Score with per-pillar detail.
const cfg = $('Set API Configuration').first().json;
const all = $input.first().json;

const patentData = all.patents || all[0] || {};
const orangeBookData = all.orangeBook || all[1] || {};
const andaData = all.anda || all[2] || {};
const marketData = all.market || all[3] || {};

const exclusivityEntries = orangeBookData.exclusivities || orangeBookData.results || (Array.isArray(orangeBookData) ? orangeBookData : []);
const patentEntries = patentData.patents || (Array.isArray(patentData) ? patentData : []);
const andaEntries = andaData.filings || andaData.results || (Array.isArray(andaData) ? andaData : []);
const marketEntries = marketData.products || (Array.isArray(marketData) ? marketData : []);

const now = Date.now();
const DAY_MS = 1000 * 60 * 60 * 24;
const WINDOW_DAYS = cfg.expiryWindowDays || 1095;

const opportunities = [];

for (const ex of exclusivityEntries) {
  const ndaNumber = ex.applicationNumber || ex.nda_number;
  const drugName = ex.drugName || ex.trade_name || 'Unknown';
  const exclusivityExpiry = ex.exclusivityExpiryDate || ex.expiration_date;
  if (!exclusivityExpiry) continue;

  const daysUntilExpiry = Math.round((new Date(exclusivityExpiry).getTime() - now) / DAY_MS);
  if (daysUntilExpiry < 0 || daysUntilExpiry > WINDOW_DAYS) continue;

  const relatedPatents = patentEntries.filter(p => (p.applicationNumber || p.nda_number) === ndaNumber || (p.drugName || '').toLowerCase() === drugName.toLowerCase());
  const latestPatentExpiryMs = relatedPatents.length
    ? Math.max(...relatedPatents.map(p => new Date(p.expirationDate || p.patent_expiration).getTime()))
    : new Date(exclusivityExpiry).getTime();
  const daysUntilPatentExpiry = Math.round((latestPatentExpiryMs - now) / DAY_MS);
  const remainingPatentCount = relatedPatents.filter(p => new Date(p.expirationDate || p.patent_expiration).getTime() > now).length;
  const hasPTEExtension = relatedPatents.some(p => p.patentTermExtension || p.pte);

  const competingFilers = andaEntries.filter(a => (a.applicationNumber || a.nda_number) === ndaNumber || (a.drugName || '').toLowerCase() === drugName.toLowerCase());
  const paragraphIVCount = competingFilers.filter(a => /paragraph iv/i.test(a.certificationType || a.paragraph || '')).length;

  const marketEntry = marketEntries.find(m => (m.applicationNumber || m.nda_number) === ndaNumber || (m.drugName || '').toLowerCase() === drugName.toLowerCase());
  const annualRevenueUSD = Number(marketEntry?.annualRevenueUSD ?? marketEntry?.revenue ?? 0);

  const soonest = Math.min(daysUntilExpiry, daysUntilPatentExpiry);
  let exclusivityTimingScore;
  if (soonest <= 365) exclusivityTimingScore = 100;
  else if (soonest <= 730) exclusivityTimingScore = 70;
  else if (soonest <= 1095) exclusivityTimingScore = 40;
  else exclusivityTimingScore = 15;

  let marketValueScore;
  if (annualRevenueUSD >= 1+1234567890) marketValueScore = 100;
  else if (annualRevenueUSD >= 5+1234567890) marketValueScore = 80;
  else if (annualRevenueUSD >= 1+1234567890) marketValueScore = 50;
  else if (annualRevenueUSD > 0) marketValueScore = 25;
  else marketValueScore = 10;

  const filerCount = competingFilers.length;
  let competitiveIntensityScore;
  if (filerCount === 0) competitiveIntensityScore = 100;
  else if (filerCount <= 2) competitiveIntensityScore = 65;
  else if (filerCount <= 5) competitiveIntensityScore = 35;
  else competitiveIntensityScore = 10;

  let patentBarrierScore = 100 - Math.min(70, remainingPatentCount * 10) - (hasPTEExtension ? 15 : 0);
  patentBarrierScore = Math.max(0, patentBarrierScore);

  const WEIGHTS = { timing: 0.3, market: 0.3, competition: 0.25, barrier: 0.15 };
  const overallScore = Math.round(
    exclusivityTimingScore * WEIGHTS.timing +
    marketValueScore * WEIGHTS.market +
    competitiveIntensityScore * WEIGHTS.competition +
    patentBarrierScore * WEIGHTS.barrier
  );

  let priorityTier = 'low';
  if (overallScore >= cfg.opportunityHighThreshold) priorityTier = 'high';
  else if (overallScore >= cfg.opportunityWatchThreshold) priorityTier = 'watch';

  opportunities.push({
    ...cfg,
    ndaNumber,
    drugName,
    exclusivityExpiry,
    daysUntilExpiry,
    latestPatentExpiryDate: new Date(latestPatentExpiryMs).toISOString(),
    daysUntilPatentExpiry,
    remainingPatentCount,
    hasPTEExtension,
    paragraphIVCount,
    competingFilerCount: filerCount,
    annualRevenueUSD,
    pillars: { exclusivityTimingScore, marketValueScore, competitiveIntensityScore, patentBarrierScore },
    overallScore,
    priorityTier
  });
}

return opportunities.map(o => ({ json: o }));

// Correlate signals across exclusivity, patent, and filing data that a
// single-pillar view would miss, per opportunity.
const items = $input.all();

return items.map(it => {
  const o = it.json;
  const flags = [];

  if (o.competingFilerCount === 0 && o.daysUntilExpiry <= 365) {
    flags.push({ type: 'first_mover_opportunity', note: 'No generic filers yet and exclusivity expires within a year - strong first-to-file window.' });
  }
  if (o.paragraphIVCount > 0 && o.remainingPatentCount > 0) {
    flags.push({ type: 'active_litigation_risk', note: 'Paragraph IV challenges exist while patents remain unexpired - likely active or upcoming patent litigation.' });
  }
  if (o.hasPTEExtension && (o.daysUntilPatentExpiry - o.daysUntilExpiry) > 180) {
    flags.push({ type: 'exclusivity_patent_gap', note: 'Regulatory exclusivity expires well before the patent term extension - the real opportunity window may be narrower than it looks.' });
  }

  return { json: { ...o, correlationFlags: flags, correlationCount: flags.length } };
});

const aiResponse = $input.first().json;
const opportunity = $('Loop Over High-Priority Opportunities').first().json;

let report;
try {
  const rawText = aiResponse.content?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  report = JSON.parse(cleaned);
} catch (e) {
  report = { executiveSummary: '', opportunityThesis: '', estimatedPeakSalesUSD: 0, recommendedAction: '', keyRisks: ['Report generation failed to parse'], timeToActRecommendation: '' };
}

return [{
  json: {
    ...opportunity,
    ...report
  }
}];

