// Recheck pass: re-score just this one opportunity using freshly refetched
// competitive filing data, keeping the rest of the original context.
const refreshed = $input.first().json;
const opportunity = $('Parse BD Report Data').first().json;

const andaEntries = refreshed.filings || refreshed.results || (Array.isArray(refreshed) ? refreshed : []);
const competingFilers = andaEntries.filter(a => (a.applicationNumber || a.nda_number) === opportunity.ndaNumber || (a.drugName || '').toLowerCase() === (opportunity.drugName || '').toLowerCase());
const filerCount = competingFilers.length;

let competitiveIntensityScore;
if (filerCount === 0) competitiveIntensityScore = 100;
else if (filerCount <= 2) competitiveIntensityScore = 65;
else if (filerCount <= 5) competitiveIntensityScore = 35;
else competitiveIntensityScore = 10;

const pillars = { ...opportunity.pillars, competitiveIntensityScore };
const WEIGHTS = { timing: 0.3, market: 0.3, competition: 0.25, barrier: 0.15 };
const overallScore = Math.round(
  pillars.exclusivityTimingScore * WEIGHTS.timing +
  pillars.marketValueScore * WEIGHTS.market +
  pillars.competitiveIntensityScore * WEIGHTS.competition +
  pillars.patentBarrierScore * WEIGHTS.barrier
);

let priorityTier = 'low';
if (overallScore >= opportunity.opportunityHighThreshold) priorityTier = 'high';
else if (overallScore >= opportunity.opportunityWatchThreshold) priorityTier = 'watch';

return [{
  json: {
    ...opportunity,
    competingFilerCount: filerCount,
    pillars,
    overallScore,
    priorityTier,
    recheckPass: 'recheck'
  }
}];

const items = $input.all();
const topOpportunities = items
  .map(i => i.json)
  .filter(o => o.drugName)
  .slice(0, 5)
  .map(o => o.drugName + ' (' + o.overallScore + ')')
  .join(', ');

return [{
  json: {
    runCompletedAt: new Date().toISOString(),
    opportunitiesProcessed: items.length,
    topOpportunities: topOpportunities || 'none this run',
    whatsappBusinessPhoneId: items[0]?.json?.whatsappBusinessPhoneId || items[0]?.whatsappBusinessPhoneId,
    whatsappBdLeadPhone: items[0]?.json?.whatsappBdLeadPhone || items[0]?.whatsappBdLeadPhone
  }
}];
